CREATE OR REPLACE VIEW stock_balance AS
SELECT part_id, store_code,
       SUM(CASE WHEN type IN ('RECEIPT','ISSUE','TRANSFER_OUT','TRANSFER_IN','COUNT_ADJUSTMENT','ADJUSTMENT','REVERSAL') THEN quantity ELSE 0 END) AS on_hand,
       SUM(CASE WHEN type IN ('RESERVATION','RELEASE') THEN quantity ELSE 0 END) AS reserved
FROM stock_movement GROUP BY part_id, store_code;
